"use client"

import { LockIcon } from "lucide-react"
import { memo, useRef, useState, type ReactNode } from "react"

import { Button } from "@/components/ui/button"
import { SafeDial, safeDialLabels, type SafeDialChangeDetails, type SafeDialLabels } from "@/components/ui/safe-dial"
import { ScrollArea, ScrollAreaScrollbar, ScrollAreaViewport } from "@/components/ui/scroll-area"
import { useSafeVaultMotion, type SafeVaultStatus } from "@/components/ui/use-safe-vault-motion"
import { useSafeVaultStage } from "@/components/ui/use-safe-vault-stage"
import { cn } from "@/lib/utils"

type SafeVaultLabels = SafeDialLabels & {
  /** Names the region that holds the contents once the vault is unlocked. */
  contents: string
  /** Announced when the vault unlocks. */
  unlocked: string
  /** Announced when the app denies a combination. */
  denied: string
  /** Names the button that locks the vault again. */
  lock: string
}

const safeVaultLabels: SafeVaultLabels = {
  ...safeDialLabels,
  contents: "Vault contents",
  unlocked: "Unlocked",
  denied: "Wrong combination",
  lock: "Lock",
}

/** Why the vault asks for a new status: `lock` from its Lock button, `retry` once a denied code's shake has played. */
type SafeVaultStatusChangeDetails = {
  reason: "lock" | "retry"
  event: Event | undefined
}

type SafeVaultState = {
  status: SafeVaultStatus
  open: boolean
  disabled: boolean
}

type SafeVaultProps = {
  /** The accessible name of the vault and its dial. */
  label: string
  /** Set by the app once it has checked the code from `onComplete`: `denied` shakes the dial and clears the code. */
  status: SafeVaultStatus
  /**
   * Asks the app for a new status: `locked` from the Lock button (shown only with this handler), and `locked` again
   * once a denial has played, so a second wrong code can be denied too.
   */
  onStatusChange?: (status: SafeVaultStatus, details: SafeVaultStatusChangeDetails) => void
  /** Runs with the whole code when the last number is entered: check it and set `status`. */
  onComplete?: (code: string) => void
  /** The code as digits, each number padded to the same width. Pass it to control the code. */
  value?: string
  defaultValue?: string
  onValueChange?: (value: string, details: SafeDialChangeDetails) => void
  /** How many numbers the combination has; 4 by default. */
  length?: number
  /** How many numbers the dial carries, from 0; 100 by default. */
  numbers?: number
  mask?: boolean
  disabled?: boolean
  name?: string
  /**
   * What the vault holds. It isn't in the page until `status` is `unlocked`, and can't be used until the door is open.
   * Once locked it can't be used or read at once, and leaves the page when the door has shut over it.
   */
  children?: ReactNode
  labels?: Partial<SafeVaultLabels>
  /** Classes for the root; a function gets the vault's state. */
  className?: string | ((state: SafeVaultState) => string | undefined)
}

const noChange = () => {}

const Plaque = memo(function Plaque({ children }: { children: ReactNode }) {
  return (
    <div data-slot="safe-vault-plaque">
      <div data-slot="safe-vault-plaque-face">
        <ScrollArea className="size-full">
          <ScrollAreaViewport className="max-h-(--safe-vault-plaque-height)">
            <div data-slot="safe-vault-plaque-content">{children}</div>
          </ScrollAreaViewport>
          <ScrollAreaScrollbar data-agent-hidden="" />
        </ScrollArea>
      </div>
    </div>
  )
})

/**
 * A safe that opens with a combination: `SafeDial` on its door, and once the app unlocks it the door swings open and
 * the camera moves in to a plaque on the back wall holding `children`. The safe is a three.js scene drawn in a worker
 * after the controls paint; without WebGL the drawn door stays and the contents show under it.
 */
function SafeVault({
  label,
  status,
  onStatusChange,
  onComplete,
  value,
  defaultValue = "",
  onValueChange,
  length = 4,
  numbers = 100,
  mask = false,
  disabled = false,
  name,
  children,
  labels: labelOverrides,
  className,
}: SafeVaultProps) {
  const labels = { ...safeVaultLabels, ...labelOverrides }
  const [ownCode, setOwnCode] = useState(defaultValue)
  const [webgl, setWebgl] = useState(false)
  const stage = useRef<HTMLDivElement>(null)
  const layer = useRef<HTMLElement>(null)
  const code = value ?? ownCode

  const clearCode = () => {
    setOwnCode("")
    onValueChange?.("", { reason: "reset", event: undefined, cancel: noChange })
  }

  const { motion, open, closing, setRenderer } = useSafeVaultMotion(status, {
    denialPlayed: () => {
      clearCode()
      onStatusChange?.("locked", { reason: "retry", event: undefined })
    },
    relocked: clearCode,
  })

  useSafeVaultStage(stage, layer, {
    motion,
    numbers,
    onRenderer: (next) => {
      setWebgl(next)
      setRenderer(next)
    },
  })

  const unlocked = status === "unlocked"
  const shown = unlocked || closing
  const state: SafeVaultState = { status, open, disabled }
  const announcement = unlocked ? labels.unlocked : status === "denied" ? labels.denied : ""

  return (
    <div
      data-slot="safe-vault"
      data-status={status}
      data-open={open ? "" : undefined}
      data-closing={closing ? "" : undefined}
      data-vault={webgl ? "3d" : "drawn"}
      className={cn(
        "relative flex w-full flex-col overflow-hidden rounded-surface border bg-card text-card-foreground shadow-surface",
        typeof className === "function" ? className(state) : className,
      )}
    >
      <div ref={stage} data-slot="safe-vault-stage">
        <SafeDial
          label={label}
          length={length}
          numbers={numbers}
          value={code}
          onValueChange={(next, details) => {
            setOwnCode(next)
            onValueChange?.(next, details)
          }}
          onComplete={onComplete}
          mask={mask}
          disabled={disabled || unlocked}
          name={name}
          labels={{ dial: labels.dial, code: labels.code }}
          className="absolute inset-0 rounded-none border-0 bg-transparent shadow-none"
        />
        {unlocked && onStatusChange ? (
          <div data-slot="safe-vault-lock">
            <Button
              variant="secondary"
              size="icon"
              aria-label={labels.lock}
              onClick={(event) => onStatusChange("locked", { reason: "lock", event: event.nativeEvent })}
            >
              <LockIcon />
            </Button>
          </div>
        ) : null}
      </div>
      <section
        ref={layer}
        data-slot="safe-vault-contents"
        aria-label={labels.contents}
        hidden={!shown}
        inert={!open}
        aria-hidden={closing ? true : undefined}
        data-agent-hidden={closing ? "" : undefined}
      >
        <Plaque>{shown ? children : null}</Plaque>
      </section>
      <output className="sr-only">{announcement}</output>
    </div>
  )
}

export { SafeVault, safeVaultLabels }
export type { SafeVaultLabels, SafeVaultProps, SafeVaultState, SafeVaultStatus, SafeVaultStatusChangeDetails }

import { useEffectEvent, useLayoutEffect, useState, useSyncExternalStore } from "react"

import {
  denyMs,
  motionLength,
  motionTowards,
  poseAt,
  resting,
  type SafeVaultMotion,
} from "@/components/ui/safe-vault-timeline"

type SafeVaultStatus = "locked" | "denied" | "unlocked"

/**
 * The vault's motion; whether its contents are open (unlocked, and done moving when the 3D safe shows it); and whether
 * they are closing: locked, but still on the plaque while the 3D door shuts over them.
 */
type VaultMotionSnapshot = { motion: SafeVaultMotion; open: boolean; closing: boolean }

const ignore = () => {}

const epochNow = () => performance.timeOrigin + performance.now()
const reducedMotion = () => typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches

function createVaultMotion(initial: SafeVaultStatus) {
  let status = initial
  let webgl = false
  let motion = resting(initial === "unlocked" ? "unlocked" : "locked", 0)
  let played: SafeVaultMotion | null = null
  let snapshot: VaultMotionSnapshot = { motion, open: initial === "unlocked", closing: false }
  let motionTimer: ReturnType<typeof setTimeout> | undefined
  let denialTimer: ReturnType<typeof setTimeout> | undefined
  let onDenialPlayed = ignore
  let onRelocked = ignore
  const listeners = new Set<() => void>()

  const publish = () => {
    const open = status === "unlocked" && (!webgl || motion.kind === "unlocked" || played === motion)
    const closing = status !== "unlocked" && webgl && motion.kind === "locking" && played !== motion
    if (snapshot.motion === motion && snapshot.open === open && snapshot.closing === closing) return
    snapshot = { motion, open, closing }
    for (const listener of listeners) listener()
  }

  const move = (next: SafeVaultMotion, now: number) => {
    motion = next
    clearTimeout(motionTimer)
    if (next.kind === "unlocking" || next.kind === "locking") {
      motionTimer = setTimeout(
        () => {
          played = next
          publish()
        },
        Math.max(0, next.since + motionLength(next) - now),
      )
    }
  }

  return {
    subscribe(listener: () => void) {
      listeners.add(listener)
      return () => listeners.delete(listener)
    },
    snapshot: () => snapshot,
    setStatus(next: SafeVaultStatus) {
      if (next === status) return
      const from = status
      status = next
      const now = epochNow()
      const reduce = reducedMotion()
      const current = poseAt(motion, now)
      if (next === "unlocked") move(reduce ? resting("unlocked", now) : motionTowards("unlocking", current, now), now)
      else if (from === "unlocked") {
        move(reduce ? resting("locked", now) : motionTowards("locking", current, now), now)
        onRelocked()
      } else if (next === "denied") move(reduce ? resting("locked", now) : motionTowards("denied", current, now), now)
      clearTimeout(denialTimer)
      if (next === "denied") denialTimer = setTimeout(() => onDenialPlayed(), reduce ? 0 : denyMs)
      publish()
    },
    setRenderer(next: boolean) {
      webgl = next
      publish()
    },
    handle(handlers: { denialPlayed: () => void; relocked: () => void }) {
      onDenialPlayed = handlers.denialPlayed
      onRelocked = handlers.relocked
    },
    dispose() {
      clearTimeout(motionTimer)
      clearTimeout(denialTimer)
    },
  }
}

/**
 * Turns the vault's status into the motion its safe plays: unlocking (bolts, the door, the zoom onto the plaque),
 * locking, and the dial's shake when denied, at once under reduced motion. `denialPlayed` runs once the shake ends,
 * and `relocked` when an unlocked vault locks again.
 */
function useSafeVaultMotion(status: SafeVaultStatus, handlers: { denialPlayed: () => void; relocked: () => void }) {
  const [store] = useState(() => createVaultMotion(status))
  const snapshot = useSyncExternalStore(store.subscribe, store.snapshot, store.snapshot)
  const denialPlayed = useEffectEvent(handlers.denialPlayed)
  const relocked = useEffectEvent(handlers.relocked)

  useLayoutEffect(() => {
    store.handle({ denialPlayed: () => denialPlayed(), relocked: () => relocked() })
    return () => store.dispose()
  }, [store])

  useLayoutEffect(() => {
    store.setStatus(status)
  }, [store, status])

  return { ...snapshot, setRenderer: store.setRenderer }
}

export { createVaultMotion, useSafeVaultMotion }
export type { SafeVaultStatus, VaultMotionSnapshot }

import { useEffect, useEffectEvent, useRef, type RefObject } from "react"

import {
  createSafeVaultStage,
  supportsSafeVaultStage,
  type SafeVaultStage,
  type VaultInput,
} from "@/components/ui/safe-vault-stage"

/**
 * Puts the 3D safe behind the dial in `host` after the controls have painted, with the plaque in `layer` on its back
 * wall, and hands it each motion. Without WebGL, on the server and in tests, the drawn door stays.
 */
function useSafeVaultStage(
  host: RefObject<HTMLElement | null>,
  layer: RefObject<HTMLElement | null>,
  input: VaultInput & { onRenderer: (webgl: boolean) => void },
) {
  const stage = useRef<SafeVaultStage | null>(null)
  const { motion, numbers, onRenderer } = input
  const rendered = useEffectEvent((webgl: boolean) => onRenderer(webgl))

  useEffect(() => {
    const element = host.current
    const contents = layer.current
    if (!element || !contents || !supportsSafeVaultStage()) return
    const created = createSafeVaultStage(element, {
      layer: contents,
      onRenderer: (webgl) => rendered(webgl),
    })
    stage.current = created
    return () => {
      created.dispose()
      stage.current = null
    }
  }, [host, layer])

  useEffect(() => {
    stage.current?.update({ motion, numbers })
  }, [motion, numbers])
}

export { useSafeVaultStage }

const openDegrees = 100

/** The moving parts at a moment: bolts from out (0) to in (1), the door's swing, the interior light and the zoom. */
type Pose = {
  bolts: number
  doorDegrees: number
  light: number
  zoom: number
  wobbleDegrees: number
}

/**
 * What the vault is doing since `since` (ms since the epoch), starting from the pose `from`. `locked` and `unlocked`
 * rest; `unlocking`, `locking` and `denied` play once and then rest locked, unlocked and locked. An unlock or a lock
 * that interrupts another starts from where that one had the vault, so nothing jumps.
 */
type SafeVaultMotion = {
  kind: "locked" | "unlocking" | "unlocked" | "locking" | "denied"
  since: number
  from: Pose
}

const unlockTimes = { bolts: 450, pause: 220, door: 1150, zoom: 1000 }
const lockTimes = { zoom: 600, door: 900, bolts: 350 }
const denyMs = 520
const unlockMs = unlockTimes.bolts + unlockTimes.pause + unlockTimes.door + unlockTimes.zoom
const lockMs = lockTimes.zoom + lockTimes.door + lockTimes.bolts

const clamp01 = (value: number) => Math.max(0, Math.min(1, value))
const easeInOut = (t: number) => (t < 0.5 ? 2 * t * t : 1 - (-2 * t + 2) ** 2 / 2)
const overshoot = (t: number) => 1 + 2.2 * (t - 1) ** 3 + 1.2 * (t - 1) ** 2

const lockedPose: Pose = {
  bolts: 0,
  doorDegrees: 0,
  light: 0,
  zoom: 0,
  wobbleDegrees: 0,
}
const unlockedPose: Pose = {
  bolts: 1,
  doorDegrees: openDegrees,
  light: 1,
  zoom: 1,
  wobbleDegrees: 0,
}

const phase = (elapsed: number, start: number, length: number) =>
  length <= 0 ? (elapsed >= start ? 1 : 0) : clamp01((elapsed - start) / length)

function unlockPhases(from: Pose) {
  const bolts = unlockTimes.bolts * (1 - from.bolts)
  const pause = from.doorDegrees > 0 ? 0 : unlockTimes.pause
  const door = unlockTimes.door * clamp01(1 - from.doorDegrees / openDegrees)
  const zoom = unlockTimes.zoom * (1 - from.zoom)
  return { bolts, doorStart: bolts + pause, door, zoomStart: bolts + pause + door, zoom }
}

function lockPhases(from: Pose) {
  const zoom = lockTimes.zoom * from.zoom
  const door = lockTimes.door * clamp01(from.doorDegrees / openDegrees)
  const bolts = lockTimes.bolts * from.bolts
  return { zoom, door, boltsStart: zoom + door, bolts }
}

function motionLength({ kind, from }: SafeVaultMotion) {
  if (kind === "unlocking") {
    const { zoomStart, zoom } = unlockPhases(from)
    return zoomStart + zoom
  }
  if (kind === "locking") {
    const { boltsStart, bolts } = lockPhases(from)
    return boltsStart + bolts
  }
  return kind === "denied" ? denyMs : 0
}

/** Whether a motion has played out at `now` (ms since the epoch), so nothing moves until the next one. */
const motionDone = (motion: SafeVaultMotion, now: number) => now - motion.since >= motionLength(motion)

const towards = (from: number, to: number, t: number) => from + (to - from) * t

function unlockingPose(from: Pose, elapsed: number): Pose {
  const times = unlockPhases(from)
  const door = phase(elapsed, times.doorStart, times.door)
  return {
    bolts: towards(from.bolts, 1, easeInOut(phase(elapsed, 0, times.bolts))),
    doorDegrees: towards(from.doorDegrees, openDegrees, door === 0 ? 0 : overshoot(door)),
    light: towards(from.light, 1, clamp01(door * 1.6)),
    zoom: towards(from.zoom, 1, phase(elapsed, times.zoomStart, times.zoom)),
    wobbleDegrees: 0,
  }
}

function lockingPose(from: Pose, elapsed: number): Pose {
  const times = lockPhases(from)
  const door = easeInOut(phase(elapsed, times.zoom, times.door))
  return {
    bolts: towards(from.bolts, 0, easeInOut(phase(elapsed, times.boltsStart, times.bolts))),
    doorDegrees: towards(from.doorDegrees, 0, door),
    light: towards(from.light, 0, door),
    zoom: towards(from.zoom, 0, phase(elapsed, 0, times.zoom)),
    wobbleDegrees: 0,
  }
}

/** The moving parts at `now` (ms since the epoch). */
function poseAt(motion: SafeVaultMotion, now: number): Pose {
  const elapsed = Math.max(0, now - motion.since)
  if (motion.kind === "unlocking") return unlockingPose(motion.from, elapsed)
  if (motion.kind === "locking") return lockingPose(motion.from, elapsed)
  if (motion.kind === "unlocked") return unlockedPose
  if (motion.kind === "denied" && elapsed < denyMs) {
    const t = elapsed / denyMs
    return {
      ...lockedPose,
      wobbleDegrees: Math.sin(t * Math.PI * 7) * 5 * (1 - t),
    }
  }
  return lockedPose
}

/** A vault at rest, locked or unlocked, since `since`. */
const resting = (kind: "locked" | "unlocked", since: number): SafeVaultMotion => ({
  kind,
  since,
  from: kind === "locked" ? lockedPose : unlockedPose,
})

/** The motion that takes the vault to `kind` from the pose `current` has it in at `now`, with no jump. */
function motionTowards(kind: "unlocking" | "locking" | "denied", current: Pose, now: number): SafeVaultMotion {
  return { kind, since: now, from: { ...current, wobbleDegrees: 0 } }
}

export {
  denyMs,
  lockedPose,
  lockMs,
  motionDone,
  motionLength,
  motionTowards,
  openDegrees,
  poseAt,
  resting,
  unlockedPose,
  unlockMs,
}
export type { Pose, SafeVaultMotion }

import { openDegrees, type Pose } from "@/components/ui/safe-vault-timeline"

type Vector = { x: number; y: number; z: number }
type StagePoint = { x: number; y: number }
type Rect = { left: number; top: number; width: number; height: number }

/** Where the camera looks from: degrees around and above `target`, and its distance, in centimetres. */
type Framing = {
  azimuthDegrees: number
  elevationDegrees: number
  distance: number
  target: Vector
}

const cameraFovDegrees = 26
const halfFovTan = Math.tan((cameraFovDegrees * Math.PI) / 360)

const width = 56
const height = 78
const depth = 54
const lift = 2.2
const frame = 3.5
const openingWidth = width - frame * 2
const openingHeight = height - frame * 2
const bodyCenterY = lift + height / 2
const doorGap = 0.35
const doorWidth = openingWidth - doorGap * 2
const doorHeight = openingHeight - doorGap * 2
const doorDepth = 9
const doorFrontZ = depth + 0.15
const pivot: Vector = { x: width / 2 + 1.1, y: bodyCenterY, z: depth + 1.3 }
const doorCenter: Vector = {
  x: -pivot.x,
  y: 0,
  z: doorFrontZ - doorDepth / 2 - pivot.z,
}
const backInside = 2.5
const liningFront = depth - doorDepth - 0.6
const floorInside = bodyCenterY - openingHeight / 2
const ceilingInside = bodyCenterY + openingHeight / 2
const panelSeam = 0.35
const panelDepth = 0.5
const panelFace = backInside + 0.05 + panelDepth
const panelRows = [20, 27, 23.9] as const
const plaqueRowCenter = floorInside + 0.05 + panelRows[0] + panelRows[1] / 2
const plaqueWidth = 36
const plaqueMinHeight = 14
const plaqueMaxHeight = 24
const plaqueFace = panelFace + 0.25
const screwInset = 1.5
const dialRadius = 9.8
const dialOnDoor: Vector = { x: doorCenter.x, y: 4, z: doorFrontZ - pivot.z }
const boltCount = 5

const closedFraming: Framing = {
  azimuthDegrees: -24,
  elevationDegrees: 11,
  distance: 245,
  target: { x: 3, y: 33, z: 44 },
}
const openFraming: Framing = {
  azimuthDegrees: -15,
  elevationDegrees: 9,
  distance: 232,
  target: { x: 10, y: 32, z: 44 },
}
const closedSpan = 70
const openSpan = 82
const minPlaquePixels = 340

const clamp01 = (value: number) => Math.max(0, Math.min(1, value))
const easeInOutCubic = (t: number) => (t < 0.5 ? 4 * t ** 3 : 1 - (-2 * t + 2) ** 3 / 2)

const mix = (a: number, b: number, t: number) => a + (b - a) * t
const mixVector = (a: Vector, b: Vector, t: number): Vector => ({
  x: mix(a.x, b.x, t),
  y: mix(a.y, b.y, t),
  z: mix(a.z, b.z, t),
})
const mixFraming = (a: Framing, b: Framing, t: number): Framing => ({
  azimuthDegrees: mix(a.azimuthDegrees, b.azimuthDegrees, t),
  elevationDegrees: mix(a.elevationDegrees, b.elevationDegrees, t),
  distance: mix(a.distance, b.distance, t),
  target: mixVector(a.target, b.target, t),
})

const backedOffToFit = (framing: Framing, spanCm: number, aspect: number): Framing => ({
  ...framing,
  distance: Math.max(framing.distance, spanCm / (2 * halfFovTan * aspect)),
})

/**
 * The camera at rest on the plaque: nearly square to the back wall, close enough that the plaque is at least
 * `minPlaquePixels` wide (or 86% of a narrow stage), and on a wide stage far enough to keep a sliver of the frame.
 */
function settledFraming(aspect: number, stageWidth: number): Framing {
  const frontPlane = depth - backInside
  const frameSliverDistance = frontPlane + (openingWidth * 1.22) / (2 * halfFovTan * aspect)
  const plaqueShare = Math.min(0.86, minPlaquePixels / Math.max(1, stageWidth))
  const readableDistance = plaqueWidth / plaqueShare / (2 * halfFovTan * aspect)
  return {
    azimuthDegrees: 4,
    elevationDegrees: 2,
    distance: Math.min(frameSliverDistance, readableDistance),
    target: { x: -1, y: plaqueRowCenter, z: backInside },
  }
}

/** The camera for a pose on a stage: from the closed safe to the open door as it swings, then into the plaque. */
function framingFor(pose: Pose, aspect: number, stageWidth: number): Framing {
  const swung = mixFraming(
    backedOffToFit(closedFraming, closedSpan, aspect),
    backedOffToFit(openFraming, openSpan, aspect),
    clamp01(pose.doorDegrees / openDegrees),
  )
  return pose.zoom > 0 ? mixFraming(swung, settledFraming(aspect, stageWidth), easeInOutCubic(pose.zoom)) : swung
}

const add = (a: Vector, b: Vector, scale = 1): Vector => ({
  x: a.x + b.x * scale,
  y: a.y + b.y * scale,
  z: a.z + b.z * scale,
})
const dot = (a: Vector, b: Vector) => a.x * b.x + a.y * b.y + a.z * b.z
const cross = (a: Vector, b: Vector): Vector => ({
  x: a.y * b.z - a.z * b.y,
  y: a.z * b.x - a.x * b.z,
  z: a.x * b.y - a.y * b.x,
})
const unit = (a: Vector): Vector => {
  const length = Math.hypot(a.x, a.y, a.z) || 1
  return { x: a.x / length, y: a.y / length, z: a.z / length }
}

/** Where the camera of a framing stands, in the scene's centimetres. */
function cameraPosition({ azimuthDegrees, elevationDegrees, distance, target }: Framing): Vector {
  const azimuth = (azimuthDegrees * Math.PI) / 180
  const elevation = (elevationDegrees * Math.PI) / 180
  return {
    x: target.x + Math.sin(azimuth) * Math.cos(elevation) * distance,
    y: target.y + Math.sin(elevation) * distance,
    z: target.z + Math.cos(azimuth) * Math.cos(elevation) * distance,
  }
}

type Projection = (point: Vector) => StagePoint & { depth: number }

/** Projects scene points onto a stage of this width-to-height ratio: 0 to 1 from the left and the top. */
function projection(framing: Framing, aspect: number): Projection {
  const position = cameraPosition(framing)
  const forward = unit(add(framing.target, position, -1))
  const right = unit(cross(forward, { x: 0, y: 1, z: 0 }))
  const up = cross(right, forward)
  return (point) => {
    const offset = add(point, position, -1)
    const along = dot(offset, forward)
    return {
      x: (dot(offset, right) / (along * halfFovTan * aspect) + 1) / 2,
      y: (1 - dot(offset, up) / (along * halfFovTan)) / 2,
      depth: along,
    }
  }
}

/** A point fixed to the door, in the door's own frame, where the door's swing takes it. */
function onDoor(point: Vector, doorDegrees: number): Vector {
  const angle = (doorDegrees * Math.PI) / 180
  return {
    x: pivot.x + point.x * Math.cos(angle) + point.z * Math.sin(angle),
    y: pivot.y + point.y,
    z: pivot.z - point.x * Math.sin(angle) + point.z * Math.cos(angle),
  }
}

/** The plaque's corners, clockwise from the top left, for a plaque `plaqueHeightCm` tall. */
function plaqueCorners(plaqueHeightCm: number): Vector[] {
  const top = plaqueRowCenter + plaqueHeightCm / 2
  const bottom = plaqueRowCenter - plaqueHeightCm / 2
  return [
    { x: -plaqueWidth / 2, y: top, z: plaqueFace },
    { x: plaqueWidth / 2, y: top, z: plaqueFace },
    { x: plaqueWidth / 2, y: bottom, z: plaqueFace },
    { x: -plaqueWidth / 2, y: bottom, z: plaqueFace },
  ]
}

const openingCorners: Vector[] = [
  { x: -openingWidth / 2, y: ceilingInside, z: depth },
  { x: openingWidth / 2, y: ceilingInside, z: depth },
  { x: openingWidth / 2, y: floorInside, z: depth },
  { x: -openingWidth / 2, y: floorInside, z: depth },
]

/** The door's free edge, on its front and on its back face: two lines that bound what it hides. */
function doorEdges(doorDegrees: number): [Vector, Vector][] {
  const x = doorCenter.x - doorWidth / 2
  return [doorCenter.z + doorDepth / 2, doorCenter.z - doorDepth / 2].map((z) => [
    onDoor({ x, y: doorHeight / 2, z }, doorDegrees),
    onDoor({ x, y: -doorHeight / 2, z }, doorDegrees),
  ])
}

function clipBy(polygon: StagePoint[], [a, b]: [StagePoint, StagePoint], keep: StagePoint): StagePoint[] {
  const side = (p: StagePoint) => (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x)
  const keepSign = Math.sign(side(keep))
  const inside = (p: StagePoint) => side(p) * keepSign >= 0
  const result: StagePoint[] = []
  polygon.forEach((current, index) => {
    const previous = polygon[(index + polygon.length - 1) % polygon.length] ?? current
    const crossing = () => {
      const t = side(previous) / (side(previous) - side(current))
      return {
        x: previous.x + (current.x - previous.x) * t,
        y: previous.y + (current.y - previous.y) * t,
      }
    }
    if (inside(current)) {
      if (!inside(previous)) result.push(crossing())
      result.push(current)
    } else if (inside(previous)) result.push(crossing())
  })
  return result
}

/** The part of the opening the camera sees past the frame and the door, in stage pixels. */
function visibleOpening(project: Projection, doorDegrees: number, stage: { width: number; height: number }) {
  const toPixels = (point: Vector) => {
    const projected = project(point)
    return {
      x: projected.x * stage.width,
      y: projected.y * stage.height,
      depth: projected.depth,
    }
  }
  const opening = openingCorners.map(toPixels)
  const corner = opening[0]
  if (!corner) return []
  let visible: StagePoint[] = opening
  for (const [top, bottom] of doorEdges(doorDegrees)) {
    const from = toPixels(top)
    const to = toPixels(bottom)
    if (from.depth > 0 && to.depth > 0) visible = clipBy(visible, [from, to], corner)
  }
  return visible
}

/** The area of a polygon in square pixels. */
function polygonArea(points: StagePoint[]) {
  let twice = 0
  points.forEach((point, index) => {
    const next = points[(index + 1) % points.length] ?? point
    twice += point.x * next.y - next.x * point.y
  })
  return Math.abs(twice) / 2
}

/**
 * The CSS `matrix3d` values that map a `width` × `height` box, from its top left corner, onto four stage points,
 * clockwise from the top left: the projective map of a plane, exact for a flat plaque.
 */
function planeMatrix(corners: StagePoint[], boxWidth: number, boxHeight: number): number[] | null {
  const [p0, p1, p2, p3] = corners
  if (!p0 || !p1 || !p2 || !p3) return null
  const sx = p0.x - p1.x + p2.x - p3.x
  const sy = p0.y - p1.y + p2.y - p3.y
  const dx1 = p1.x - p2.x
  const dx2 = p3.x - p2.x
  const dy1 = p1.y - p2.y
  const dy2 = p3.y - p2.y
  const denominator = dx1 * dy2 - dx2 * dy1
  if (Math.abs(denominator) < 1e-9) return null
  const g = (sx * dy2 - dx2 * sy) / denominator
  const h = (dx1 * sy - sx * dy1) / denominator
  const a = p1.x - p0.x + g * p1.x
  const b = p3.x - p0.x + h * p3.x
  const d = p1.y - p0.y + g * p1.y
  const e = p3.y - p0.y + h * p3.y
  return [
    a / boxWidth,
    d / boxWidth,
    0,
    g / boxWidth,
    b / boxHeight,
    e / boxHeight,
    0,
    h / boxHeight,
    0,
    0,
    1,
    0,
    p0.x,
    p0.y,
    0,
    1,
  ]
}

/** Where `matrix3d` values take a point of the box, as the browser draws it. */
function applyMatrix(matrix: number[], x: number, y: number): StagePoint {
  const at = (index: number) => matrix[index] ?? 0
  const w = at(3) * x + at(7) * y + at(15)
  return {
    x: (at(0) * x + at(4) * y + at(12)) / w,
    y: (at(1) * x + at(5) * y + at(13)) / w,
  }
}

/** The bounding box of the dial on the closed door, in stage pixels. */
function dialRect(project: Projection, stage: { width: number; height: number }): Rect {
  const center = onDoor(dialOnDoor, 0)
  const points = [
    { ...center, x: center.x - dialRadius },
    { ...center, x: center.x + dialRadius },
    { ...center, y: center.y - dialRadius },
    { ...center, y: center.y + dialRadius },
  ].map(project)
  const xs = points.map((point) => point.x * stage.width)
  const ys = points.map((point) => point.y * stage.height)
  const left = Math.min(...xs)
  const top = Math.min(...ys)
  return {
    left,
    top,
    width: Math.max(...xs) - left,
    height: Math.max(...ys) - top,
  }
}

/** The plaque's width in CSS pixels once the camera has settled, the width its contents lay out at. */
function plaqueLayoutWidth(stage: { width: number; height: number }) {
  const aspect = stage.width / stage.height
  const project = projection(settledFraming(aspect, stage.width), aspect)
  const [topLeft, topRight, bottomRight, bottomLeft] = plaqueCorners(plaqueMinHeight).map(project)
  if (!topLeft || !topRight || !bottomRight || !bottomLeft) return minPlaquePixels
  const across = (a: StagePoint, b: StagePoint) => Math.hypot((b.x - a.x) * stage.width, (b.y - a.y) * stage.height)
  return Math.round((across(topLeft, topRight) + across(bottomLeft, bottomRight)) / 2)
}

/** The plaque's height in centimetres for contents `contentPixels` tall at `pixelsPerCm`, within the panel. */
const plaqueHeightFor = (contentPixels: number, pixelsPerCm: number) =>
  Math.max(plaqueMinHeight, Math.min(plaqueMaxHeight, contentPixels / Math.max(0.001, pixelsPerCm)))

