/**
 * What the vault draws: its motion, the dial's turn in degrees and how many numbers it carries, the plaque's height in
 * centimetres, and whether it may move on its own (in view, without reduced motion).
 */
type VaultState = {
  motion: SafeVaultMotion
  dialDegrees: number
  numbers: number
  plaqueHeight: number
  moving: boolean
}

type VaultScene = {
  software: boolean
  prepare: () => Promise<void>
  setSize: (size: StageSize) => void
  render: (state: VaultState, now: number) => void
  dispose: () => void
}

const environmentCubeSize = 128
const shadowMapSize = 512
const boltLockedX = 0.4
const boltRetractedX = 2.7
const warmLightCandela = 9000

function part(geometry: BufferGeometry, material: Material | Material[], x = 0, y = 0, z = 0) {
  const mesh = new Mesh(geometry, material)
  mesh.castShadow = true
  mesh.position.set(x, y, z)
  return mesh
}

function facing(mesh: Mesh) {
  mesh.rotation.x = Math.PI / 2
  return mesh
}

function boltHeights() {
  const span = doorHeight - 18
  return Array.from({ length: boltCount }, (_, index) => -span / 2 + (span * index) / (boltCount - 1))
}

const hingeHeights = [openingHeight / 2 - 12, -openingHeight / 2 + 12]

function body(m: Materials) {
  const group = new Group()
  const bevel = 0.8
  const outline = roundedRect(width - bevel * 2, height - bevel * 2, 2.6)
  outline.holes.push(roundedRect(openingWidth + bevel * 2, openingHeight + bevel * 2, 0.6))
  const extruded = new ExtrudeGeometry(outline, {
    depth: depth - bevel * 2,
    bevelEnabled: true,
    bevelThickness: bevel,
    bevelSize: bevel,
    bevelSegments: 4,
    curveSegments: 10,
  })
  group.add(part(extruded, [m.steel, m.steel], 0, bodyCenterY, bevel))
  group.add(
    part(new BoxGeometry(openingWidth + 1, openingHeight + 1, backInside), m.jamb, 0, bodyCenterY, backInside / 2),
  )
  for (const x of [-width / 2 + 5, width / 2 - 5]) {
    for (const z of [5, depth - 5]) group.add(part(new CylinderGeometry(2.2, 2.4, lift, 24), m.rubber, x, lift / 2, z))
  }
  for (const y of boltHeights()) {
    const hole = new Mesh(new CircleGeometry(1.7, 32), m.hole)
    hole.rotation.y = Math.PI / 2
    hole.position.set(-openingWidth / 2 + 0.02, bodyCenterY + y, doorFrontZ - doorDepth / 2)
    group.add(hole)
  }
  for (const y of hingeHeights) {
    group.add(part(new CylinderGeometry(1.6, 1.6, 10, 32), m.hinge, pivot.x, bodyCenterY + y, pivot.z))
    for (const end of [-1, 1]) {
      group.add(part(new CylinderGeometry(0.9, 1.6, 1.2, 32), m.hinge, pivot.x, bodyCenterY + y + end * 5.6, pivot.z))
    }
    group.add(part(new BoxGeometry(0.4, 7, 4), m.steelBox, width / 2 + 0.2, bodyCenterY + y, depth - 1.2))
  }
  return group
}

function interior(m: Materials) {
  const group = new Group()
  const inset = 0.05
  const w = openingWidth - inset * 2
  const h = openingHeight - inset * 2
  const d = liningFront - backInside
  const midZ = backInside + d / 2
  const plane = (pw: number, ph: number, x: number, y: number, z: number, rx: number, ry: number) => {
    const mesh = new Mesh(new PlaneGeometry(pw, ph), m.felt)
    mesh.position.set(x, y, z)
    mesh.rotation.set(rx, ry, 0)
    group.add(mesh)
  }
  plane(d, h, -w / 2, bodyCenterY, midZ, 0, Math.PI / 2)
  plane(d, h, w / 2, bodyCenterY, midZ, 0, -Math.PI / 2)
  plane(w, d, 0, ceilingInside - inset, midZ, Math.PI / 2, 0)
  plane(w, d, 0, floorInside + inset, midZ, -Math.PI / 2, 0)
  const back = new Mesh(new PlaneGeometry(w, h), m.seam)
  back.position.set(0, bodyCenterY, backInside + inset)
  group.add(back)
  let rowBottom = floorInside + inset
  for (const [row, rowHeight] of panelRows.entries()) {
    const columns = row === 1 ? 1 : 2
    const tileWidth = w / columns
    for (let column = 0; column < columns; column++) {
      const tile = new Mesh(
        new RoundedBoxGeometry(tileWidth - panelSeam, rowHeight - panelSeam, panelDepth, 2, 0.15),
        m.panel,
      )
      tile.position.set(-w / 2 + tileWidth * (column + 0.5), rowBottom + rowHeight / 2, panelFace - panelDepth / 2)
      group.add(tile)
    }
    rowBottom += rowHeight
  }
  group.add(part(new BoxGeometry(openingWidth - 8, 0.35, 1.2), m.led, 0, ceilingInside - 0.3, liningFront - 1.2))
  const screws = [-1, 1].flatMap((x) =>
    [-1, 1].map((y) => {
      const screw = facing(part(new CylinderGeometry(0.55, 0.6, 0.5, 24), m.satin))
      screw.userData = { x, y }
      group.add(screw)
      return screw
    }),
  )
  const placeScrews = (plaqueHeight: number) => {
    for (const screw of screws) {
      const { x = 0, y = 0 } = screw.userData
      screw.position.set(
        Number(x) * (plaqueWidth / 2 - screwInset),
        plaqueRowCenter + Number(y) * (plaqueHeight / 2 - screwInset),
        plaqueFace,
      )
    }
  }
  return { group, placeScrews }
}

function dial(m: Materials) {
  const group = new Group()
  group.add(facing(part(new CylinderGeometry(9.4, 9.8, 0.9, 96), m.chrome, 0, 0, 0.45)))
  group.add(part(new TorusGeometry(9.15, 0.35, 16, 96), m.chrome, 0, 0, 0.9))
  group.add(part(new BoxGeometry(0.7, 1.6, 0.6), m.hole, 0, 8.55, 1.1))
  const rotor = new Group()
  rotor.add(facing(part(new CylinderGeometry(8, 8.1, 1.6, 128, 1, true), m.knurled, 0, 0, 1.75)))
  rotor.add(part(new CircleGeometry(8, 128), m.face, 0, 0, 2.56))
  rotor.add(facing(part(new CylinderGeometry(3.4, 3.6, 3.2, 64, 1, true), m.knurled, 0, 0, 4.15)))
  rotor.add(part(new CircleGeometry(3.4, 64), m.satin, 0, 0, 5.76))
  rotor.add(part(new TorusGeometry(3.3, 0.18, 12, 64), m.chrome, 0, 0, 5.7))
  group.add(rotor)
  group.position.set(dialOnDoor.x, dialOnDoor.y, dialOnDoor.z)
  return { group, rotor }
}

function door(m: Materials) {
  const group = new Group()
  group.position.set(pivot.x, pivot.y, pivot.z)
  const bevel = 0.7
  const slab = new ExtrudeGeometry(roundedRect(doorWidth - bevel * 2, doorHeight - bevel * 2, 1.4), {
    depth: doorDepth - bevel * 2,
    bevelEnabled: true,
    bevelThickness: bevel,
    bevelSize: bevel,
    bevelSegments: 4,
    curveSegments: 10,
  })
  group.add(part(slab, [m.steel, m.steel], doorCenter.x, doorCenter.y, doorCenter.z - doorDepth / 2 + bevel))
  const backFace = doorCenter.z - doorDepth / 2
  group.add(
    part(
      new RoundedBoxGeometry(doorWidth - 9, doorHeight - 9, 1, 3, 0.4),
      m.doorInner,
      doorCenter.x,
      0,
      backFace - 0.3,
    ),
  )
  for (const x of [-1, 1]) {
    for (const y of [-1, 1]) {
      const screw = part(
        new CylinderGeometry(0.6, 0.6, 0.4, 16),
        m.satin,
        doorCenter.x + x * (doorWidth / 2 - 7),
        y * (doorHeight / 2 - 7),
        backFace - 0.9,
      )
      group.add(facing(screw))
    }
  }
  const bolts = boltHeights().map((y) => {
    const bolt = part(
      new CapsuleGeometry(1.6, 4, 8, 24),
      m.chrome,
      doorCenter.x - doorWidth / 2 + boltLockedX,
      y,
      doorCenter.z,
    )
    bolt.rotation.z = Math.PI / 2
    group.add(bolt)
    return bolt
  })
  for (const y of hingeHeights)
    group.add(part(new BoxGeometry(4.6, 7, 0.4), m.steelBox, -3.3, y, doorFrontZ - pivot.z + 0.2))
  const { group: dialGroup, rotor } = dial(m)
  group.add(dialGroup)
  return { group, bolts, rotor }
}

function floorShadows() {
  const floor = new Mesh(new PlaneGeometry(600, 600), new ShadowMaterial({ opacity: 0.3 }))
  floor.rotation.x = -Math.PI / 2
  floor.receiveShadow = true
  const contact = canvasTexture(sized("contactShadow"), contactShadow, false)
  const blob = new Mesh(
    new PlaneGeometry(width * 1.5, depth * 1.5),
    new MeshBasicMaterial({
      color: 0x000000,
      alphaMap: contact,
      transparent: true,
      depthWrite: false,
    }),
  )
  blob.rotation.x = -Math.PI / 2
  blob.position.set(0, 0.05, depth / 2)
  return [floor, blob]
}

function lights(scene: Scene) {
  const key = new DirectionalLight(0xfff3e6, 2.4)
  key.position.set(-70, 220, 110)
  key.target.position.set(0, 30, 30)
  key.castShadow = true
  key.shadow.mapSize.set(shadowMapSize, shadowMapSize)
  Object.assign(key.shadow.camera, {
    left: -110,
    right: 110,
    top: 110,
    bottom: -110,
    near: 10,
    far: 500,
  })
  key.shadow.radius = 4
  key.shadow.bias = -0.0006
  key.shadow.normalBias = 0.4
  const rim = new DirectionalLight(0xcfe0ff, 1.8)
  rim.position.set(120, 80, -90)
  scene.add(key, key.target, rim)
}

const posed = (a: Pose, b: Pose | null) => b !== null && a.bolts === b.bolts && a.doorDegrees === b.doorDegrees

/** The safe in a dark studio, drawn into `canvas`; it throws when the canvas has no WebGL. */
function createVaultScene(canvas: Surface, size: StageSize): VaultScene {
  const renderer = new WebGLRenderer({ canvas, antialias: true, alpha: true })
  const software = isSoftwareRenderer(renderer)
  renderer.toneMapping = ACESFilmicToneMapping
  renderer.toneMappingExposure = 1.3
  renderer.shadowMap.enabled = true
  renderer.shadowMap.type = PCFShadowMap
  renderer.shadowMap.autoUpdate = false

  const scene = new Scene()
  const environment = studioEnvironment(renderer, studio, environmentCubeSize)
  scene.environment = environment.texture

  const m = materials()
  const { group: doorGroup, bolts, rotor } = door(m)
  const { group: inside, placeScrews } = interior(m)
  scene.add(body(m), inside, doorGroup, ...floorShadows())
  lights(scene)
  const warm = new PointLight(0xffb468, 0, 0, 2)
  warm.position.set(0, ceilingInside - 4, liningFront - 5)
  scene.add(warm)

  const camera = new PerspectiveCamera(cameraFovDegrees, 1, 5, 2000)
  let stage = size
  let shadowPose: Pose | null = null
  let plaqueHeight = Number.NaN
  let numbers = 0

  const engraveDial = (count: number) => {
    numbers = count
    const previous = m.face.map
    const face = canvasTexture(sized("dialFace"), dialFace(count), true)
    m.face.map = face
    m.face.bumpMap = face
    m.face.needsUpdate = true
    previous?.dispose()
  }
  engraveDial(100)

  const setSize = (next: StageSize) => {
    stage = next
    renderer.setPixelRatio(stagePixelRatio(software, next.pixelRatio))
    renderer.setSize(Math.max(1, next.width), Math.max(1, next.height), false)
    camera.aspect = next.width > 0 && next.height > 0 ? next.width / next.height : 1
    camera.updateProjectionMatrix()
    shadowPose = null
  }
  setSize(size)

  return {
    software,
    prepare: () => prepareScene(renderer, scene, camera),
    setSize,
    render(state, now) {
      const pose = poseAt(state.motion, now)
      const framing = framingFor(pose, camera.aspect, stage.width)
      const position = cameraPosition(framing)
      camera.position.set(position.x, position.y, position.z)
      camera.lookAt(framing.target.x, framing.target.y, framing.target.z)
      rotor.rotation.z = (-(state.dialDegrees + pose.wobbleDegrees) * Math.PI) / 180
      const boltX = doorCenter.x - doorWidth / 2 + boltLockedX + (boltRetractedX - boltLockedX) * pose.bolts
      for (const bolt of bolts) bolt.position.x = boltX
      doorGroup.rotation.y = (pose.doorDegrees * Math.PI) / 180
      warm.intensity = pose.light * warmLightCandela
      m.led.emissiveIntensity = pose.light * 3
      if (state.numbers !== numbers) engraveDial(state.numbers)
      if (state.plaqueHeight !== plaqueHeight) {
        plaqueHeight = state.plaqueHeight
        placeScrews(plaqueHeight)
      }
      if (!posed(pose, shadowPose)) {
        shadowPose = pose
        renderer.shadowMap.needsUpdate = true
      }
      renderer.render(scene, camera)
    },
    dispose() {
      disposeAll(scene)
      environment.dispose()
      renderer.dispose()
    },
  }
}

export { createVaultScene, environmentCubeSize, shadowMapSize }
export type { VaultScene, VaultState }

import { MeshPhysicalMaterial, MeshStandardMaterial, Shape } from "three"

import { brushedLines, knurl, orangePeel, radialBrush, safeTextureSizes } from "@/components/ui/safe-vault-textures"
import type { Softbox } from "@/lib/three-studio"
import { canvasTexture, noise, repeating } from "@/lib/three-textures"

const studio: readonly Softbox[] = [
  { width: 40, height: 14, intensity: 7, at: [0, 45, 10] },
  { width: 50, height: 30, intensity: 1.6, at: [-10, 10, 45] },
  { width: 10, height: 60, intensity: 4, at: [-45, 10, 20], tint: 0xfff1e0 },
  { width: 8, height: 50, intensity: 3, at: [45, 15, -10], tint: 0xdfe8ff },
  { width: 60, height: 6, intensity: 1.2, at: [0, 6, 46] },
]

const sized = (name: keyof typeof safeTextureSizes) => {
  const { width: w, height: h } = safeTextureSizes[name]
  return { width: w, height: h }
}

function roundedRect(w: number, h: number, radius: number) {
  const shape = new Shape()
  const x = -w / 2
  const y = -h / 2
  shape.moveTo(x + radius, y)
  shape.lineTo(x + w - radius, y)
  shape.quadraticCurveTo(x + w, y, x + w, y + radius)
  shape.lineTo(x + w, y + h - radius)
  shape.quadraticCurveTo(x + w, y + h, x + w - radius, y + h)
  shape.lineTo(x + radius, y + h)
  shape.quadraticCurveTo(x, y + h, x, y + h - radius)
  shape.lineTo(x, y + radius)
  shape.quadraticCurveTo(x, y, x + radius, y)
  return shape
}

function materials() {
  const peel = repeating(canvasTexture(sized("peel"), orangePeel(7), false), 0.09)
  const peelBox = repeating(canvasTexture(sized("peel"), orangePeel(9), false), 4)
  const peelRough = repeating(
    canvasTexture(sized("peelRoughness"), (c, s) => noise(c, s, 150, 40, false, 3), false),
    0.07,
  )
  const knurled = repeating(canvasTexture(sized("knurl"), knurl, false), 3, 1)
  const brush = canvasTexture(sized("radialBrush"), radialBrush, false)
  const brushed = canvasTexture(sized("brushedLines"), brushedLines, false)
  const powder = {
    color: 0x3a3c40,
    roughness: 0.58,
    metalness: 0.15,
    bumpScale: 0.5,
    clearcoat: 0.12,
    clearcoatRoughness: 0.55,
  }
  const dimInside = { envMapIntensity: 0.22 }
  return {
    steel: new MeshPhysicalMaterial({
      ...powder,
      bumpMap: peel,
      roughnessMap: peelRough,
    }),
    steelBox: new MeshPhysicalMaterial({ ...powder, bumpMap: peelBox }),
    jamb: new MeshStandardMaterial({
      color: 0x2a2b2e,
      roughness: 0.5,
      metalness: 0.4,
      bumpMap: peel,
      bumpScale: 0.3,
    }),
    doorInner: new MeshStandardMaterial({
      color: 0x1b1c1f,
      roughness: 0.7,
      metalness: 0.3,
      bumpMap: peelBox,
      bumpScale: 0.3,
    }),
    chrome: new MeshStandardMaterial({
      color: 0xe9ebef,
      metalness: 1,
      roughness: 0.12,
    }),
    satin: new MeshStandardMaterial({
      color: 0xd4d7dc,
      metalness: 1,
      roughness: 0.26,
      bumpMap: brush,
      bumpScale: 0.15,
    }),
    knurled: new MeshStandardMaterial({
      color: 0xd8dbe0,
      metalness: 1,
      roughness: 0.22,
      bumpMap: knurled,
      bumpScale: 1,
    }),
    face: new MeshStandardMaterial({
      color: 0xe4e7eb,
      metalness: 1,
      roughness: 0.32,
      bumpScale: 1.2,
    }),
    hinge: new MeshStandardMaterial({
      color: 0x2a2b2e,
      metalness: 0.8,
      roughness: 0.32,
    }),
    hole: new MeshStandardMaterial({ color: 0x18181a, roughness: 0.8, metalness: 0.4 }),
    rubber: new MeshStandardMaterial({ color: 0x0b0b0b, roughness: 0.9 }),
    felt: new MeshStandardMaterial({
      color: 0x3b3028,
      roughness: 1,
      ...dimInside,
    }),
    panel: new MeshStandardMaterial({
      color: 0x77716a,
      metalness: 0.6,
      roughness: 0.4,
      bumpMap: brushed,
      bumpScale: 0.25,
      ...dimInside,
    }),
    seam: new MeshStandardMaterial({
      color: 0x0c0b0a,
      roughness: 1,
      ...dimInside,
    }),
    led: new MeshStandardMaterial({
      color: 0x111111,
      emissive: 0xffc27a,
      emissiveIntensity: 0,
    }),
  }
}

type Materials = ReturnType<typeof materials>

export { materials, roundedRect, sized, studio }
export type { Materials }

import { seededRandom, type Context2D } from "@/lib/three-textures"

/** The side of each canvas texture in pixels, and how many the scene draws, for its texture memory. */
const safeTextureSizes = {
  peel: { width: 256, height: 256, count: 2 },
  peelRoughness: { width: 128, height: 128, count: 1 },
  dialFace: { width: 512, height: 512, count: 1 },
  radialBrush: { width: 256, height: 256, count: 1 },
  brushedLines: { width: 256, height: 256, count: 1 },
  knurl: { width: 256, height: 8, count: 1 },
  contactShadow: { width: 128, height: 128, count: 1 },
} as const

function orangePeel(seed: number) {
  return (context: Context2D, size: number) => {
    const random = seededRandom(seed)
    context.fillStyle = "#808080"
    context.fillRect(0, 0, size, size)
    for (let index = 0; index < size * size * 0.06; index++) {
      const x = random() * size
      const y = random() * size
      const radius = 1.5 + random() * 3.5
      const gradient = context.createRadialGradient(x, y, 0, x, y, radius)
      gradient.addColorStop(0, random() > 0.5 ? "rgb(255 255 255 / 0.22)" : "rgb(0 0 0 / 0.22)")
      gradient.addColorStop(1, "rgb(128 128 128 / 0)")
      context.fillStyle = gradient
      context.fillRect(x - radius, y - radius, radius * 2, radius * 2)
    }
  }
}

const numberedEvery = (numbers: number) => (numbers > 60 ? 10 : 5)

/** A dial face engraved with `numbers` ticks, numbered like the drawn dial, counting up anticlockwise from the top. */
function dialFace(numbers: number) {
  return (context: Context2D, size: number) => engrave(context, size, numbers)
}

function engrave(context: Context2D, size: number, numbers: number) {
  const every = numberedEvery(numbers)
  const center = size / 2
  context.fillStyle = "#ffffff"
  context.fillRect(0, 0, size, size)
  context.translate(center, center)
  context.strokeStyle = "#141414"
  context.fillStyle = "#141414"
  for (let tick = 0; tick < numbers; tick++) {
    const major = tick % every === 0
    const middle = !major && tick % (every / 2) === 0
    context.save()
    context.rotate((-tick * Math.PI * 2) / numbers)
    context.lineWidth = major ? size * 0.008 : size * 0.0045
    context.beginPath()
    context.moveTo(0, -center * 0.97)
    context.lineTo(0, -center * (major ? 0.84 : middle ? 0.87 : 0.9))
    context.stroke()
    if (major) {
      context.font = `700 ${String(Math.round(size * 0.075))}px Arial, sans-serif`
      context.textAlign = "center"
      context.textBaseline = "middle"
      context.fillText(String(tick), 0, -center * 0.72)
    }
    context.restore()
  }
  context.lineWidth = size * 0.004
  context.beginPath()
  context.arc(0, 0, center * 0.6, 0, Math.PI * 2)
  context.stroke()
}

function radialBrush(context: Context2D, size: number) {
  const random = seededRandom(5)
  const center = size / 2
  context.fillStyle = "#7a7a7a"
  context.fillRect(0, 0, size, size)
  context.translate(center, center)
  for (let ring = 0; ring < 600; ring++) {
    const shade = String(Math.round(100 + random() * 50))
    context.strokeStyle = `rgb(${shade} ${shade} ${shade} / 0.5)`
    context.lineWidth = 0.6
    context.beginPath()
    context.arc(0, 0, random() * center, 0, Math.PI * 2)
    context.stroke()
  }
}

function brushedLines(context: Context2D, width: number, height: number) {
  const random = seededRandom(21)
  context.fillStyle = "#808080"
  context.fillRect(0, 0, width, height)
  for (let line = 0; line < height * 3; line++) {
    const shade = String(Math.round(90 + random() * 80))
    context.fillStyle = `rgb(${shade} ${shade} ${shade} / 0.35)`
    context.fillRect(random() * width * 0.3 - width * 0.3, random() * height, width * (0.4 + random()), 0.6 + random())
  }
}

function knurl(context: Context2D, width: number, height: number) {
  const ridges = 60
  const step = width / ridges
  for (let ridge = 0; ridge < ridges; ridge++) {
    const gradient = context.createLinearGradient(ridge * step, 0, (ridge + 1) * step, 0)
    gradient.addColorStop(0, "#202020")
    gradient.addColorStop(0.5, "#f0f0f0")
    gradient.addColorStop(1, "#202020")
    context.fillStyle = gradient
    context.fillRect(ridge * step, 0, step, height)
  }
}

function contactShadow(context: Context2D, size: number) {
  const gradient = context.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2)
  gradient.addColorStop(0, "rgb(150 150 150)")
  gradient.addColorStop(0.55, "rgb(60 60 60)")
  gradient.addColorStop(1, "rgb(0 0 0)")
  context.fillStyle = gradient
  context.fillRect(0, 0, size, size)
}

export { brushedLines, contactShadow, dialFace, knurl, orangePeel, radialBrush, safeTextureSizes }

import { createVaultScene, type VaultState } from "@/components/ui/safe-vault-scene"
import { motionDone, resting } from "@/components/ui/safe-vault-timeline"
import { createStageRunner, serveStageRunner, type RunnerFactory } from "@/lib/three-stage-runner"

const epochNow = () => performance.timeOrigin + performance.now()

/** Draws the safe into `canvas` once per change, and every frame while it unlocks or locks. `null` without WebGL. */
const createSafeVaultRunner: RunnerFactory<VaultState> = (canvas, size, events) =>
  createStageRunner<VaultState>(
    canvas,
    size,
    events,
    (surface, initial) => {
      const scene = createVaultScene(surface, initial)
      return {
        software: scene.software,
        prepare: scene.prepare,
        setSize: scene.setSize,
        animating: (state) => state.moving && !motionDone(state.motion, epochNow()),
        render: (state) => scene.render(state, epochNow()),
        dispose: scene.dispose,
      }
    },
    {
      motion: resting("locked", 0),
      dialDegrees: 0,
      numbers: 100,
      plaqueHeight: 18,
      moving: false,
    },
  )

/** Serves the safe's runner to the page from its worker. */
const serveSafeVaultRunner = () => serveStageRunner(createSafeVaultRunner)

export { createSafeVaultRunner, serveSafeVaultRunner }
